struct nglQuad { char data[0x64]; };
typedef float time_value_t;

void nglSetQuadRect(nglQuad *, float, float, float, float);
void nglSetQuadUV(nglQuad *, float, float, float, float);
void nglRotateQuad(nglQuad *, float, float, float);

class PanelQuad
{
    bool isAnim;
    int fade;
    float fade_alpha;
    float fade_timer;
    float mask;
    int maskType;
    void *anim;
    nglQuad quad;
    bool drawOn;
    int rotate;
    float rotation;
    float rotate_x;
    float rotate_y;
    int layer;
    float r, g, b, a;
    float x1, y1, x2, y2;
    char remaining_fields[0xc8];
    float u1, v1, u2, v2;
public:
    void Update(time_value_t time_inc);
};

void PanelQuad::Update(time_value_t time_inc)
{
	// Fade in.
	if(fade == 1)
	{
		fade_alpha += (time_inc/fade_timer)*a;
		if(fade_alpha >= a)
			fade = 0;
	}
	// Fade out.
	else if(fade == -1)
	{
		fade_alpha -= (time_inc/fade_timer)*a;
		if(fade_alpha <= 0.0f)
		{
			fade = 0;
			drawOn = false;
		}
	}
	// Constant fade.
	else if(fade == 2)
	{

	}

	if (maskType != 0)
	{
		if (mask > 1.0f)
			mask = 2.0f - mask;

		if (maskType == 1)
		{
			float tmp_x = (x2-x1)*mask + x1;
			float tmp_u = (u2-u1)*mask + u1;
			nglSetQuadRect(&quad, x1, y1, tmp_x, y2);
			nglSetQuadUV(&quad, u1, v1, tmp_u, v2);
		}
		else if (maskType == 2)
		{
			float tmp_x = x2 - (x2-x1)*mask;
			float tmp_u = u2 - (u2-u1)*mask;
			nglSetQuadRect(&quad, tmp_x, y1, x2, y2);
			nglSetQuadUV(&quad, tmp_u, v1, u2, v2);
		}
		else if (maskType == 3)
		{
			float tmp_y = (y1-y2)*mask + y2;
			float tmp_v = (v1-v2)*mask + v2;
			nglSetQuadRect(&quad, x1, tmp_y, x2, y2);
			nglSetQuadUV(&quad, u1, tmp_v, u2, v2);
		}

		if (rotate == 1)
			nglRotateQuad(&quad, (x2-x1)/2.0f+x1, (y2-y1)/2.0f+y1, rotation);
		if (rotate == 2)
			nglRotateQuad(&quad, rotate_x, rotate_y, rotation);
	}
}
